@pytest.fixture
def t() -> np.ndarray:
    return np.linspace(0, 1, 200)


@pytest.fixture
def sine_signal(t: np.ndarray) -> Signal:
    return Signal(time=t, values=np.sin(2 * np.pi * 5 * t), name="sine")


