class TestConstants:
    def test_default_line_frequency(self):
        assert DEFAULT_LINE_FREQUENCY_HZ == 60.0

    def test_harmonic_constants(self):
        assert PERIODIC_NOISE_2ND_HARMONIC == 0.3
        assert PERIODIC_NOISE_3RD_HARMONIC == 0.1


